BEGIN;
CREATE TABLE IF NOT EXISTS credit_lifecycle_cases(id BIGSERIAL PRIMARY KEY,tenant_id TEXT NOT NULL,project_id TEXT NOT NULL,developer_organization_id TEXT NOT NULL,jurisdiction TEXT NOT NULL,methodology_id TEXT NOT NULL,methodology_version TEXT NOT NULL,state TEXT NOT NULL CHECK(state IN('draft','methodology_locked','monitoring','calculation_submitted','verification','verified','issued','retired','rejected','reversed')),record JSONB NOT NULL,idempotency_key TEXT NOT NULL,version INTEGER NOT NULL DEFAULT 1,created_by TEXT NOT NULL,created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),UNIQUE(tenant_id,project_id),UNIQUE(tenant_id,idempotency_key));
CREATE TABLE IF NOT EXISTS credit_lifecycle_events(id BIGSERIAL PRIMARY KEY,case_id BIGINT NOT NULL REFERENCES credit_lifecycle_cases(id),tenant_id TEXT NOT NULL,actor_id TEXT NOT NULL,event_type TEXT NOT NULL,from_state TEXT,to_state TEXT,idempotency_key TEXT,evidence_digest TEXT NOT NULL,details JSONB NOT NULL DEFAULT '{}'::jsonb,created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),UNIQUE(case_id,idempotency_key));
CREATE TABLE IF NOT EXISTS credit_issuance_serials(id BIGSERIAL PRIMARY KEY,case_id BIGINT NOT NULL REFERENCES credit_lifecycle_cases(id),registry TEXT NOT NULL,registry_issuance_id TEXT NOT NULL,serial_start TEXT NOT NULL,serial_end TEXT NOT NULL,quantity NUMERIC(20,6) NOT NULL CHECK(quantity>0),created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),UNIQUE(registry,registry_issuance_id),UNIQUE(registry,serial_start,serial_end));
CREATE TABLE IF NOT EXISTS credit_retirements(id BIGSERIAL PRIMARY KEY,case_id BIGINT NOT NULL REFERENCES credit_lifecycle_cases(id),registry_retirement_id TEXT NOT NULL UNIQUE,beneficiary TEXT NOT NULL,purpose TEXT NOT NULL,quantity NUMERIC(20,6) NOT NULL CHECK(quantity>0),evidence_digest TEXT NOT NULL,created_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE TABLE IF NOT EXISTS credit_sync_jobs(id BIGSERIAL PRIMARY KEY,tenant_id TEXT NOT NULL,provider TEXT NOT NULL CHECK(provider IN('mrv_sensor','lab','gis','remote_sensing','registry','ledger','marketplace','kyc')),idempotency_key TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'queued' CHECK(status IN('queued','running','succeeded','failed','quarantined')),payload JSONB NOT NULL,requested_by TEXT NOT NULL,attempts INTEGER NOT NULL DEFAULT 0,failure_code TEXT,created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),UNIQUE(tenant_id,provider,idempotency_key));
CREATE INDEX IF NOT EXISTS idx_credit_cases_tenant_state ON credit_lifecycle_cases(tenant_id,state,methodology_id);
COMMIT;
